window.REPORT_PRELOAD_CACHE["TXN.html"] = {"version":"05b350579840297beb59da146e2b7b622387f4bdb20e7983b0e7fae41a6af9f8","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>德州仪器 Texas Instruments (NASDAQ: TXN) 深度研究报告：模拟芯片之王、12英寸制造战略与工业汽车周期复苏</title>\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Chart.js -->\n    <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n    <!-- Google Fonts -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n    <script>\n    tailwind.config = {\n        darkMode: 'class',\n        theme: {\n            extend: {\n                fontFamily: {\n                    sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n                    mono: ['JetBrains Mono', 'monospace'],\n                },\n                colors: {\n                    navy: {\n                        950: '#070B14',\n                        900: '#0F172A',\n                        800: '#1E293B',\n                        700: '#334155',\n                    },\n                    txnred: {\n                        400: '#F87171',\n                        500: '#CC0000',\n                        600: '#990000',\n                    },\n                    accent: {\n                        500: '#2563EB',\n                        600: '#1D4ED8',\n                    },\n                    teal: {\n                        500: '#0D9488',\n                        600: '#0F766E',\n                    }\n                }\n            }\n        }\n    }\n    </script>\n\n    <style>\n        ::-webkit-scrollbar { width: 6px; height: 6px; }\n        ::-webkit-scrollbar-track { background: transparent; }\n        ::-webkit-scrollbar-thumb { background: #94A3B8; border-radius: 3px; }\n        .dark ::-webkit-scrollbar-thumb { background: #475569; }\n\n        @media print {\n            #sidebar, #mobile-header, #theme-toggle-btn, .no-print { display: none !important; }\n            main { margin-left: 0 !important; padding: 0 !important; }\n            section { break-inside: avoid; }\n        }\n\n        .report-card {\n            transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n        }\n        .report-card:hover {\n            transform: translateY(-2px);\n        }\n\n        .nav-link.active {\n            background: linear-gradient(90deg, rgba(204, 0, 0, 0.22) 0%, rgba(37, 99, 235, 0.08) 100%);\n            border-left: 3px solid #CC0000;\n            color: #FFFFFF;\n            font-weight: 600;\n        }\n    </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-txnred-500 selection:text-white transition-colors duration-200\">\n\n    <!-- 顶部全局阅读进度条 -->\n    <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n        <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-txnred-500 via-accent-500 to-teal-500 w-0 transition-all duration-150\"></div>\n    </div>\n\n    <!-- 移动端顶部导航栏 -->\n    <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n        <div class=\"flex items-center space-x-2.5\">\n            <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-txnred-500 to-txnred-600 flex items-center justify-center font-extrabold text-white shadow\">\n                TI\n            </div>\n            <div>\n                <div class=\"text-[11px] text-txnred-400 font-semibold tracking-wider uppercase\">NASDAQ: TXN · Equity Research</div>\n                <div class=\"text-sm font-bold leading-tight\">德州仪器 TXN 深度研究报告</div>\n            </div>\n        </div>\n        <div class=\"flex items-center space-x-2\">\n            <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n                <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n            </button>\n            <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n                <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n            </button>\n        </div>\n    </header>\n\n    <!-- 移动端抽屉菜单 -->\n    <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n        <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n        <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n            <div>\n                <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n                    <span class=\"font-bold text-white text-base\">TXN 研报目录导航</span>\n                    <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n                        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n                    </button>\n                </div>\n                <ul class=\"mt-4 space-y-1.5 text-sm\">\n                    <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n                    <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务架构与模拟芯片霸主地位</a></li>\n                    <li><a href=\"#sec-cap\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 12英寸晶圆厂战略与自由现金流拐点</a></li>\n                    <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 竞争格局与同行对标</a></li>\n                    <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n                    <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n                    <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n                </ul>\n            </div>\n            <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n                <p>全球半导体与模拟芯片研究组</p>\n                <p class=\"mt-1\">数据基准：2026年11月 (FY26 / FY27E)</p>\n            </div>\n        </nav>\n    </div>\n\n    <!-- 桌面端左侧固定侧边导航栏 -->\n    <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n        <div>\n            <!-- 品牌头部 -->\n            <div class=\"p-5 border-b border-slate-800/80\">\n                <div class=\"flex items-center space-x-3\">\n                    <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-txnred-500 to-txnred-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-txnred-500/25\">\n                        TXN\n                    </div>\n                    <div>\n                        <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-txnred-400 bg-txnred-500/15 px-2 py-0.5 rounded\">NASDAQ: TXN</span>\n                        <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">德州仪器深度研报</h2>\n                    </div>\n                </div>\n                <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n                    全球模拟芯片与嵌入式处理器霸主 · 12英寸制造自主化战略引领者\n                </p>\n            </div>\n\n            <!-- 实时股票快照徽章 -->\n            <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">FY2025/26 营收恢复</span>\n                    <span class=\"font-mono font-bold text-white\">$17.5B - $18.2B</span>\n                </div>\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">模拟芯片市场份额</span>\n                    <span class=\"font-mono font-bold text-txnred-400\">~19% (全球绝对龙头)</span>\n                </div>\n                <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n                    <span class=\"text-slate-400\">12英寸产能占比</span>\n                    <span class=\"font-mono font-bold text-teal-400\">向 60%+ 迈进 (长期成本优势)</span>\n                </div>\n            </div>\n\n            <!-- 导航目录 -->\n            <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n                <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n                <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n                    <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-txnred-400 mr-2\">00</span>执行摘要与核心指标</span>\n                    </a>\n                    <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务架构与模拟芯片霸主地位</span>\n                    </a>\n                    <a href=\"#sec-cap\" data-target=\"sec-cap\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>12英寸晶圆厂战略与自由现金流拐点</span>\n                    </a>\n                    <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>竞争格局与同行对标</span>\n                    </a>\n                    <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n                    </a>\n                    <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n                    </a>\n                    <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n                    </a>\n                </nav>\n            </div>\n        </div>\n\n        <!-- 底部工具栏 -->\n        <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n            <div class=\"flex items-center justify-between\">\n                <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n                <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n                    <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n                    <svg class=\"w-3.5 h-3.5 text-txnred-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                    <span class=\"dark:hidden\">深色护眼模式</span>\n                    <span class=\"hidden dark:inline\">机构亮色模式</span>\n                </button>\n            </div>\n            <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-txnred-500 hover:bg-txnred-600 text-white text-xs font-extrabold transition shadow-sm\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n                <span>打印 / 导出 PDF 研报</span>\n            </button>\n        </div>\n    </aside>\n\n    <!-- 主内容区 -->\n    <main class=\"lg:ml-[280px] min-h-screen\">\n        <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n            <!-- =========================================================\n            00. 封面与执行摘要\n            ========================================================= -->\n            <section id=\"sec-exec\" class=\"scroll-mt-20\">\n                <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n                    <div class=\"flex flex-wrap items-center gap-2\">\n                        <span class=\"px-2.5 py-1 rounded-md bg-txnred-500/15 text-txnred-600 dark:text-txnred-400 font-bold border border-txnred-500/30\">评级：审慎买入 / 周期底部长线配置</span>\n                        <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：FY2026–FY2027 工业汽车去库存尾声与产能自由现金流拐点</span>\n                    </div>\n                    <div class=\"flex items-center space-x-3 font-mono\">\n                        <span>覆盖时间：2026年11月</span>\n                        <span>NASDAQ: TXN</span>\n                    </div>\n                </div>\n\n                <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n                    <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#F87171 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n                    <div class=\"relative z-10\">\n                        <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-txnred-500/20 border border-txnred-500/40 text-txnred-400 text-xs font-semibold mb-4\">\n                            <span class=\"w-2 h-2 rounded-full bg-txnred-400 animate-pulse\"></span>\n                            <span>CORE THESIS · 全球模拟芯片绝对霸主：穿越景气度周期的 12英寸晶圆厂制造自主化与长期自由现金流复苏</span>\n                        </div>\n                        <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n                            德州仪器 Texas Instruments (NASDAQ: TXN) 深度研究报告：模拟芯片之王、12英寸制造战略与工业汽车周期复苏\n                        </h1>\n                        <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n                            德州仪器（TI）作为全球模拟芯片（Analog）与嵌入式处理器（Embedded Processing）的绝对龙头，占据近 <strong>19%</strong> 的全球市场份额。经历过去两年的工业与汽车市场去库存筑底后，TI 正迎来需求温和复苏。\n                            公司坚定执行长达数年的 <strong class=\"text-txnred-400\">12英寸晶圆厂资本开支（Capex）战略</strong>，尽管短期内压制了自由现金流（FCF），但随着资本开支高峰接近尾声、内部制造比例持续提升，未来每个芯片的制造成本将显着下降，为其构筑起长达数十年、任何竞争对手难以复制的结构性成本护城河。\n                        </p>\n\n                        <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">模拟芯片龙头地位</div>\n                                <div class=\"text-white font-semibold\">全球市占率近 19%，产品品类超 8 万种，直接直销模式（Direct Sales）构建极高粘性</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">12英寸制造红利释放</div>\n                                <div class=\"text-txnred-400 font-semibold\">12英寸晶圆芯片成本比传统 8英寸降低约 40%，长期毛利率弹性空间巨大</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">工业与汽车库存出清</div>\n                                <div class=\"text-teal-400 font-semibold\">渠道库存恢复健康，汽车与工业需求在周期底部企稳回升</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 4个核心 KPI 卡片 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>全球模拟芯片市占率</span>\n                            <span class=\"p-1.5 rounded-lg bg-txnred-500/15 text-txnred-600 dark:text-txnred-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~19%</span>\n                            <span class=\"text-xs font-bold text-txnred-600 dark:text-txnred-400 bg-txnred-500/15 px-2 py-0.5 rounded\">全球绝对第一</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            凭借庞大的产品组合与直销体系，稳居全球模拟及嵌入式处理芯片龙头宝座。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>模拟芯片营收占比</span>\n                            <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~75% - 80%</span>\n                            <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">核心业务支柱</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            包含信号链（Signal Chain）与电源管理（Power Management），广泛服务于工业和汽车。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>长期毛利率目标</span>\n                            <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">60% – 65%</span>\n                            <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">12英寸降本驱动</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            随着 12英寸晶圆厂产能利用率爬坡，长期毛利率潜力随制造成本下降而显著释放。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>工业与汽车下游占比</span>\n                            <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">&gt;70%</span>\n                            <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">长寿命高门槛</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            高度聚焦工业自动化、新能源车及车载电子，客户黏性极高，生命周期可达数十年。\n                        </p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            01. 业务架构与模拟芯片霸主地位\n            ========================================================= -->\n            <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-txnred-600 dark:text-txnred-400\">Section 01 · Business Architecture & Analog Leadership</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务架构与模拟芯片霸主地位：超 8 万种产品与直销模式</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">模拟芯片全球市占率 ~19% · 工业汽车占收超 70%</span>\n                </div>\n\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n                    <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n                            <div>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2022–FY2027E 分部营收演进与模拟芯片核心地位</h3>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\">经历库存调整后稳健回升，模拟与嵌入式处理器双轮驱动</p>\n                            </div>\n                        </div>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"bizArchitectureChart\"></canvas>\n                        </div>\n                    </div>\n\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">三大核心业务支柱与渠道变革</h3>\n                            <ul class=\"space-y-4 text-sm\">\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-txnred-500/15 text-txnred-600 dark:text-txnred-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">模拟芯片（Analog：电源管理与信号链）</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            贡献公司近 80% 的营收。电源管理芯片（PMIC）与信号链产品处理现实世界的真实物理信号，拥有超 8 万种丰富规格。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">嵌入式处理器（Embedded Processing）</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            包含微控制器（MCU）和数字信号处理器（DSP），广泛应用于汽车电子、工厂自动化和物联网设备。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">直销模式转型（Direct Sales & TI.com）</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            取消传统大型分销商代理，转为线上 TI.com 直销与全球直销团队，虽然在转型期造成短暂阵痛，但长期大幅拉近了与终端客户的距离并提升了利润留存。\n                                        </p>\n                                    </div>\n                                </li>\n                            </ul>\n                        </div>\n                        <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n                            <span class=\"text-slate-500 dark:text-slate-400\">核心竞争优势</span>\n                            <span class=\"font-bold text-txnred-600 dark:text-txnred-400\">海量产品库 · 长期生命周期 · 直销高黏性</span>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            02. 12英寸晶圆厂战略与自由现金流拐点\n            ========================================================= -->\n            <section id=\"sec-cap\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · 300mm Fab Strategy & FCF Inflection</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 12英寸晶圆厂战略与自由现金流拐点：长线制造壁垒的构筑</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">12英寸芯片成本降低 ~40% · 资本开支高峰逐步过去</span>\n                </div>\n\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n                    <div class=\"lg:col-span-7 space-y-4\">\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-2\">1. 为什么坚决推行 12英寸（300mm）晶圆厂战略？</h3>\n                            <p class=\"text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                传统模拟芯片大多年使用老旧的 8英寸（200mm）晶圆生产。而德州仪器逆势大举投资建设大型 12英寸晶圆厂（如 RFAB1、RFAB2、LFAB、SM1 等）。<strong>12英寸晶圆的面积是 8英寸的 2.25 倍，单颗芯片制造成本可降低约 40%</strong>。在规模量产后，这将形成竞争对手望尘莫及的成本护城河。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-2\">2. 短期阵痛：资本开支（Capex）高峰与自由现金流压制</h3>\n                            <p class=\"text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                过去几年中，大规模的厂房建设与设备购置使 TI 的资本开支占营收比例飙升至 20%–30% 高位，导致自由现金流（FCF）阶段性承压。然而，随着全球工厂基建陆续竣工投产，资本开支强度已开始触顶回落，为未来的自由现金流爆发奠定基础。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-2\">3. 制造自主化与地缘供应链安全</h3>\n                            <p class=\"text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                通过在美国本土及全球建立高度可控的自有制造产能（Internal Manufacturing），TI 实现了对供应链、产品质量和交货周期的绝对掌控，有效规避了纯代工模式在行业景气波动时的产能挤兑风险。\n                            </p>\n                        </div>\n                    </div>\n\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">资本开支占比与自由现金流复苏轨迹</h3>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Capex 见顶回落将驱动 FCF 在 FY27 迎来强劲反弹</p>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"capexChart\"></canvas>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            03. 竞争格局与同行对标\n            ========================================================= -->\n            <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-txnred-600 dark:text-txnred-400\">Section 03 · Competitive Landscape & Peer Benchmarking</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 竞争格局与同行对标：模拟芯片双雄与差异化竞争策略</h2>\n                    </div>\n                </div>\n\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n                    <div class=\"overflow-x-auto\">\n                        <table class=\"w-full text-left border-collapse\">\n                            <thead>\n                                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                                    <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心阵营</th>\n                                    <th class=\"py-4 px-4 min-w-[140px]\">模拟芯片全球市占率</th>\n                                    <th class=\"py-4 px-4 min-w-[140px]\">制造模式策略</th>\n                                    <th class=\"py-4 px-4 min-w-[120px]\">工业与汽车聚焦度</th>\n                                    <th class=\"py-4 px-5 min-w-[240px]\">核心竞争优势与战略评估</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\">\n                                <tr class=\"bg-txnred-500/5 dark:bg-txnred-500/10 font-medium\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"flex items-center space-x-2\">\n                                            <span class=\"px-2 py-0.5 rounded bg-txnred-500 text-white text-[10px] font-extrabold\">行业龙头</span>\n                                            <span class=\"font-bold text-slate-900 dark:text-white\">德州仪器 TXN</span>\n                                        </div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">电源管理 / 信号链 / 嵌入式</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 font-bold text-txnred-600 dark:text-txnred-400\">~19% (全球第一)</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">重资产 IDM + 12英寸厂自主制造</td>\n                                    <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">&gt;70% 高度聚焦</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>规模与成本之王：</strong>通过大规模自建 12英寸晶圆厂追求极致制造成本，直销体系构建强大客户黏性。\n                                    </td>\n                                </tr>\n                                <tr class=\"hover:bg-slate-50 dark:hover:bg-navy-800/45 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">亚德诺半导体 ADI</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">高性能模拟 / 数据转换器 (ADC/DAC)</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~12% - 13% (全球第二)</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">混合 IDM + 灵活代工合作</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">工业与通信占比极高</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>高端应用专家：</strong>在高性能数据转换器、国防航天及高端工业仪器领域拥有极强的技术壁垒与定价权。\n                                    </td>\n                                </tr>\n                                <tr class=\"hover:bg-slate-50 dark:hover:bg-navy-800/45 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">英飞凌 / 意法半导体 / NXP</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">汽车电子与功率半导体巨头</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-500 dark:text-slate-400\">汽车功率与MCU领先</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">IDM 模式 (车规级认证深厚)</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">高度集中于汽车与功率</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>车规功率强者：</strong>在车载功率器件（IGBT/SiC）与车身域控 MCU 上具备极强优势，与 TI 在部分汽车模拟领域形成竞争。\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            04. 财务健康与估值体系\n            ========================================================= -->\n            <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与估值体系：穿越周期的稳健资产负债表与股东回报</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">连续多年稳定分红 · 优质资产负债表</span>\n                </div>\n\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-txnred-600 dark:text-txnred-400 uppercase\">Gross Margin</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">55% – 60%</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            受工厂初期折旧与产能利用率爬坡影响略有波动，长期随着 12英寸厂放量将向 60%+ 稳步回升。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Free Cash Flow</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">周期筑底回升</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            伴随 Capex 高峰逐步过去与工业汽车库存出清，自由现金流即将在 FY26/27 迎来显著的向上拐点。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Dividend Yield</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">稳定且高回馈</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            德州仪器历来以慷慨的股东现金回报著称，长期的股息增长记录为投资者提供坚实的防御安全垫。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Balance Sheet</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">投资级 A 级</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            资产负债结构稳健，流动性充裕，具备强大的抗风险能力与跨周期持续投资底气。\n                        </p>\n                    </div>\n                </div>\n\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2022–FY2027E 营收恢复与自由现金流拐点预测</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">工业与汽车周期触底回升，Capex 下降驱动 FCF 开启新一轮扩张周期</p>\n                        </div>\n                    </div>\n                    <div class=\"relative h-72 w-full\">\n                        <canvas id=\"valEvolutionChart\"></canvas>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            05. 投资决策与风险配置\n            ========================================================= -->\n            <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-txnred-600 dark:text-txnred-400\">Section 05 · Investment Decision & Risk Framework</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与长线配置策略</h2>\n                    </div>\n                </div>\n\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-txnred-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-txnred-500/15 text-txnred-600 dark:text-txnred-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-txnred-600 dark:text-txnred-400\">概率：30%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">工业汽车需求强劲反弹</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>全球工业自动化与新能源车需求超预期爆发，渠道库存彻底出清并引发补库潮，12英寸厂产能迅速爬坡，毛利率与 FCF 强势大增。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-txnred-600 dark:text-txnred-400\">\n                            潜在上行空间：+30% 至 +40%\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-teal-500/15 text-teal-600 dark:text-teal-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-teal-600 dark:text-teal-400\">概率：50%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">温和复苏与自由现金流改善</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>工业和汽车需求呈现温和、渐进式复苏，Capex 峰值回落，自由现金流稳步改善，估值随业绩回暖合理修复。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-teal-600 dark:text-teal-400\">\n                            潜在收益率：+15% 至 +25%（含稳定股息）\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">宏观持续低迷与产能过剩</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>宏观经济复苏乏力导致工业和汽车需求长期低迷，新建 12英寸厂面临阶段性产能闲置，折旧压力拖累毛利率。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n                            潜在下行回撤：-10% 至 -15%（高股息提供防守底线）\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n                    <h3 class=\"text-base font-bold text-txnred-400 mb-4 flex items-center space-x-2\">\n                        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n                        <span>机构级资产配置建议</span>\n                    </h3>\n                    <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n                        <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n                            <div class=\"font-bold text-white mb-1\">1. 周期底部左侧配置良机</div>\n                            <p class=\"text-slate-300 leading-relaxed\">\n                                作为模拟芯片全球王者，当前正处于工业汽车库存去化尾声与 FCF 拐点前夜，适合长线左侧布局。\n                            </p>\n                        </div>\n                        <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n                            <div class=\"font-bold text-txnred-400 mb-1\">2. 追踪 12英寸厂产能利用率</div>\n                            <p class=\"text-slate-300 leading-relaxed\">\n                                密切关注后续财报中 12英寸晶圆厂的产能爬坡进度与毛利率边际改善情况。\n                            </p>\n                        </div>\n                        <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n                            <div class=\"font-bold text-teal-400 mb-1\">3. 工业与汽车终端订单信号</div>\n                            <p class=\"text-slate-300 leading-relaxed\">\n                                监控全球汽车电子与工业自动化客户的库存天数与补库意愿，作为判断行业景气反转的领先指标。\n                            </p>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            06. 季度跟踪 KPI 核查清单\n            ========================================================= -->\n            <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Tracking KPIs</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n                    </div>\n                    <div class=\"flex items-center space-x-2 no-print\">\n                        <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-txnred-500/15 text-txnred-600 dark:text-txnred-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n                        <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n                    </div>\n                </div>\n\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n                        点击勾选机构季报追踪已验证达标的核心指标（状态自动本地保存），动态校准投资逻辑：\n                    </p>\n\n                    <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#CC0000] focus:ring-txnred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 工业与汽车终端市场订单环比回暖</span>\n                                    <span class=\"text-[11px] font-mono text-txnred-600 dark:text-txnred-400 font-semibold shrink-0\">需求复苏信号</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    跟踪工业和汽车两大核心终端市场的营收占比及客户订单取消率是否持续下降。\n                                </p>\n                            </div>\n                        </label>\n\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#CC0000] focus:ring-txnred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 资本开支（Capex）占营收比例见顶回落</span>\n                                    <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">FCF 拐点指标</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    核查 Capex 峰值是否过去，验证自由现金流由负转正或加速增长的趋势。\n                                </p>\n                            </div>\n                        </label>\n\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#CC0000] focus:ring-txnred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 毛利率（Gross Margin）触底并向 60% 稳步回升</span>\n                                    <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">成本结构改善</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    监控 12英寸晶圆厂产能利用率提升对毛利率带来的边际改善效应。\n                                </p>\n                            </div>\n                        </label>\n\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#CC0000] focus:ring-txnred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 渠道与客户库存天数恢复至正常健康水平</span>\n                                    <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">库存健康度</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    跟踪内部及渠道库存（Days of Inventory）是否回到 90-110 天的歷史健康区间。\n                                </p>\n                            </div>\n                        </label>\n\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#CC0000] focus:ring-txnred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 模拟芯片全球市占率维持或进一步扩大</span>\n                                    <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">龙头地位指标</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    评估公司在行业周期波动中对竞争对手的份额挤压或稳固能力。\n                                </p>\n                            </div>\n                        </label>\n\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#CC0000] focus:ring-txnred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 股东现金回报与股息连增记录延续</span>\n                                    <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">股东回报指标</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    监控每股分红派发及股份回购执行力度，确保长期股东价值兑现。\n                                </p>\n                            </div>\n                        </label>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            免责声明页脚\n            ========================================================= -->\n            <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n                <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n                    <span>德州仪器 Texas Instruments (NASDAQ: TXN) 深度商业与投资价值分析报告 · 机构研究版</span>\n                    <span>数据基准：FY2025/26 财报及 2026 年 11 月市场一致预期</span>\n                </div>\n                <p class=\"leading-relaxed\">\n                    <strong>免责声明：</strong>本深度研究报告基于德州仪器公开财务报告、最新季度财报及市场公开信息整理生成，旨在提供结构化的产业分析与估值研究框架。报告中涉及的营收预期、资本开支、毛利率及情景模拟均为基于公开数据的客观分析，不构成任何具体的证券买卖建议或投资承诺。投资者在做出投资决策前应进行独立尽职调查。\n                </p>\n            </footer>\n\n        </div>\n    </main>\n\n    <!-- 交互与图表脚本 -->\n    <script>\n        function toggleTheme() {\n            const html = document.documentElement;\n            html.classList.toggle('dark');\n            updateChartsTheme();\n        }\n\n        function toggleMobileMenu() {\n            const drawer = document.getElementById('mobile-drawer');\n            drawer.classList.toggle('hidden');\n        }\n\n        const sections = document.querySelectorAll('section[id]');\n        const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n        window.addEventListener('scroll', () => {\n            const scrollTop = window.scrollY;\n            const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n            const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n            document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n            let currentId = 'sec-exec';\n            sections.forEach(sec => {\n                const top = sec.offsetTop - 160;\n                if (scrollTop >= top) {\n                    currentId = sec.getAttribute('id');\n                }\n            });\n\n            navLinks.forEach(link => {\n                link.classList.remove('active');\n                const numSpan = link.querySelector('span span');\n                if (numSpan) {\n                    numSpan.classList.remove('text-txnred-400');\n                    numSpan.classList.add('text-slate-500');\n                }\n                if (link.dataset.target === currentId) {\n                    link.classList.add('active');\n                    if (numSpan) {\n                        numSpan.classList.remove('text-slate-500');\n                        numSpan.classList.add('text-txnred-400');\n                    }\n                }\n            });\n        });\n\n        const KPI_STORAGE_KEY = 'txn_research_kpi_state_v1';\n\n        function loadKpiChecklist() {\n            try {\n                const saved = localStorage.getItem(KPI_STORAGE_KEY);\n                if (saved) {\n                    const stateMap = JSON.parse(saved);\n                    document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n                        if (typeof stateMap[cb.id] === 'boolean') {\n                            cb.checked = stateMap[cb.id];\n                        }\n                    });\n                }\n            } catch (e) {}\n            updateKpiChecklist();\n        }\n\n        function updateKpiChecklist() {\n            const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n            const total = checkboxes.length;\n            let checkedCount = 0;\n            const stateMap = {};\n\n            checkboxes.forEach(cb => {\n                stateMap[cb.id] = cb.checked;\n                if (cb.checked) checkedCount++;\n            });\n\n            const pct = Math.round((checkedCount / total) * 100);\n            document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n            try {\n                localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n            } catch (e) {}\n        }\n\n        function resetKpiChecklist() {\n            document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n                cb.checked = false;\n            });\n            updateKpiChecklist();\n        }\n\n        let bizChartInstance = null;\n        let capexChartInstance = null;\n        let valEvolutionChartInstance = null;\n\n        function getChartColors() {\n            const isDark = document.documentElement.classList.contains('dark');\n            return {\n                text: isDark ? '#CBD5E1' : '#475569',\n                grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)'\n            };\n        }\n\n        function initBizChart() {\n            const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n            const colors = getChartColors();\n\n            if (bizChartInstance) bizChartInstance.destroy();\n            bizChartInstance = new Chart(ctx, {\n                type: 'bar',\n                data: {\n                    labels: ['FY2023', 'FY2024', 'FY2025', 'FY2026E', 'FY2027E'],\n                    datasets: [\n                        {\n                            label: '模拟芯片 (Analog)',\n                            data: [14.1, 13.2, 13.8, 14.9, 16.5],\n                            backgroundColor: '#CC0000',\n                            borderRadius: 4,\n                        },\n                        {\n                            label: '嵌入式处理器 (Embedded Processing)',\n                            data: [3.4, 2.8, 2.9, 3.2, 3.6],\n                            backgroundColor: '#2563EB',\n                            borderRadius: 4,\n                        },\n                        {\n                            label: '其他 (Other)',\n                            data: [0.8, 0.5, 0.5, 0.5, 0.6],\n                            backgroundColor: '#0D9488',\n                            borderRadius: 4,\n                        }\n                    ]\n                },\n                options: {\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: {\n                        legend: {\n                            position: 'bottom',\n                            labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                        },\n                        tooltip: {\n                            callbacks: {\n                                label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n                            }\n                        }\n                    },\n                    scales: {\n                        x: {\n                            stacked: true,\n                            grid: { display: false },\n                            ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                        },\n                        y: {\n                            stacked: true,\n                            max: 22,\n                            grid: { color: colors.grid },\n                            ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n                        }\n                    }\n                }\n            });\n        }\n\n        function initCapexChart() {\n            const ctx = document.getElementById('capexChart').getContext('2d');\n            const colors = getChartColors();\n\n            if (capexChartInstance) capexChartInstance.destroy();\n            capexChartInstance = new Chart(ctx, {\n                type: 'bar',\n                data: {\n                    labels: ['FY2023', 'FY2024', 'FY2025', 'FY2026E', 'FY2027E'],\n                    datasets: [\n                        {\n                            type: 'bar',\n                            label: '资本开支 Capex ($B)',\n                            data: [5.1, 4.8, 4.2, 3.8, 3.2],\n                            backgroundColor: 'rgba(204, 0, 0, 0.85)',\n                            borderRadius: 5,\n                            barThickness: 24,\n                            yAxisID: 'y'\n                        },\n                        {\n                            type: 'line',\n                            label: '自由现金流 FCF ($B)',\n                            data: [1.3, 2.1, 3.5, 4.8, 6.2],\n                            borderColor: '#0D9488',\n                            backgroundColor: '#0D9488',\n                            borderWidth: 3,\n                            pointRadius: 5,\n                            tension: 0.25,\n                            yAxisID: 'y'\n                        }\n                    ]\n                },\n                options: {\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: {\n                        legend: {\n                            position: 'bottom',\n                            labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                        }\n                    },\n                    scales: {\n                        x: {\n                            grid: { display: false },\n                            ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                        },\n                        y: {\n                            type: 'linear',\n                            position: 'left',\n                            max: 8,\n                            grid: { color: colors.grid },\n                            ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n                        }\n                    }\n                }\n            });\n        }\n\n        function initValEvolutionChart() {\n            const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n            const colors = getChartColors();\n\n            if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n            valEvolutionChartInstance = new Chart(ctx, {\n                type: 'bar',\n                data: {\n                    labels: ['FY2023', 'FY2024', 'FY2025', 'FY2026E', 'FY2027E'],\n                    datasets: [\n                        {\n                            type: 'bar',\n                            label: '全年总营收 ($B)',\n                            data: [18.3, 16.5, 17.5, 18.6, 20.7],\n                            backgroundColor: 'rgba(204, 0, 0, 0.85)',\n                            borderRadius: 5,\n                            barThickness: 24,\n                            yAxisID: 'y'\n                        },\n                        {\n                            type: 'bar',\n                            label: '全年净利润 ($B)',\n                            data: [6.0, 4.9, 5.2, 5.8, 6.9],\n                            backgroundColor: 'rgba(37, 99, 235, 0.85)',\n                            borderRadius: 5,\n                            barThickness: 24,\n                            yAxisID: 'y'\n                        },\n                        {\n                            type: 'line',\n                            label: '毛利率 Gross Margin (%)',\n                            data: [62.5, 59.8, 58.5, 60.2, 62.0],\n                            borderColor: '#0D9488',\n                            backgroundColor: '#0D9488',\n                            borderWidth: 3,\n                            pointRadius: 5,\n                            tension: 0.25,\n                            yAxisID: 'y1'\n                        }\n                    ]\n                },\n                options: {\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: {\n                        legend: {\n                            position: 'bottom',\n                            labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                        }\n                    },\n                    scales: {\n                        x: {\n                            grid: { display: false },\n                            ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                        },\n                        y: {\n                            type: 'linear',\n                            position: 'left',\n                            max: 25,\n                            grid: { color: colors.grid },\n                            ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n                        },\n                        y1: {\n                            type: 'linear',\n                            position: 'right',\n                            min: 45,\n                            max: 75,\n                            grid: { drawOnChartArea: false },\n                            ticks: { color: '#0D9488', font: { size: 11, weight: '600' }, callback: v => v + '%' }\n                        }\n                    }\n                }\n            });\n        }\n\n        function updateChartsTheme() {\n            initBizChart();\n            initCapexChart();\n            initValEvolutionChart();\n        }\n\n        window.addEventListener('DOMContentLoaded', () => {\n            loadKpiChecklist();\n            initBizChart();\n            initCapexChart();\n            initValEvolutionChart();\n        });\n    </script>\n</body>\n</html>\n"};
